// Embeds browser runtimes into a server module: the daemon bundles server code and cannot read
// node_modules at run time. Run after changing mermaid, katex or dompurify versions.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";

const require = createRequire(import.meta.url);
const read = (id) => readFileSync(require.resolve(id), "utf8");

const mermaid = read("mermaid/dist/mermaid.min.js");
const mermaidVersion = JSON.parse(read("mermaid/package.json")).version;

// DOMPurify does not export its dist folder, so resolve it from the package entry.
const purifyPath = path.join(path.dirname(require.resolve("dompurify")), "purify.min.js");
const purify = readFileSync(purifyPath, "utf8").replace(/\n?\/\/# sourceMappingURL=.*$/m, "");

const katexCssPath = require.resolve("katex/dist/katex.min.css");
const katexCss = readFileSync(katexCssPath, "utf8").replace(/src:([^;}]+)/g, (_match, sources) => {
  const woff2 = /url\((fonts\/[^)]+\.woff2)\)/.exec(sources);
  if (!woff2) return `src:${sources}`;
  const data = readFileSync(path.join(path.dirname(katexCssPath), woff2[1])).toString("base64");
  return `src:url(data:font/woff2;base64,${data}) format("woff2")`;
});

mkdirSync(new URL("../server/generated/", import.meta.url), { recursive: true });
writeFileSync(
  new URL("../server/generated/runtime.ts", import.meta.url),
  [
    "// Generated by scripts/gen-runtime.mjs. Do not edit.",
    `export const MERMAID_VERSION = ${JSON.stringify(mermaidVersion)};`,
    `export const MERMAID_SCRIPT = ${JSON.stringify(mermaid)};`,
    `export const PURIFY_SCRIPT = ${JSON.stringify(purify)};`,
    `export const KATEX_CSS = ${JSON.stringify(katexCss)};`,
    "",
  ].join("\n"),
);
console.log(`runtime written: mermaid ${mermaid.length}, dompurify ${purify.length}, katex css ${katexCss.length}`);
